    "resource": "module.eks_cluster",
    "issue": "Kubernetes API access allowed from default security group",
    "risk": "Allowing module.vpc.vpc_default_security_group_id in allowed_security_group_ids grants cluster API access to resources using the default security group, which is commonly overused and can unintentionally include many instances, increasing unauthorized access risk.",
    "remediation": "Replace module.eks_cluster.allowed_security_group_ids = [module.vpc.vpc_default_security_group_id] with a dedicated, tightly scoped security group containing only approved admin or control-plane client hosts."
  },
